import { StrictMode } from 'react';
import { createRoot } from 'react-dom/client';
import { App } from './App';
import { clearSessions, exportSessions, summarise } from './game/telemetry';
import './styles.css';

const host = document.getElementById('root');
if (!host) throw new Error('Missing #root');

createRoot(host).render(
  <StrictMode>
    <App />
  </StrictMode>,
);

// PWA shell. Dev is left alone so Vite's HMR is not fighting a cache.
if ('serviceWorker' in navigator && import.meta.env.PROD) {
  window.addEventListener('load', () => {
    void navigator.serviceWorker.register('./sw.js').catch(() => {
      // Offline support is a bonus; the game runs fine without it.
    });
  });
}

/*
 * The telemetry read-out.
 *
 * There is no button and no screen for this, because there is no audience for
 * it but us: the four numbers it answers are ours, and a child does not need a
 * panel telling them how long they took to choose. It is also the ONLY way this
 * data moves — nothing here transmits, so getting it off a device means opening
 * a console on that device and typing:
 *
 *   persia.telemetry.summary()   the four numbers
 *   persia.telemetry.export()    every session, as JSON
 *   persia.telemetry.clear()     forget the lot
 */
declare global {
  interface Window {
    persia?: { telemetry: { summary: typeof summarise; export: typeof exportSessions; clear: typeof clearSessions } };
  }
}
window.persia = { telemetry: { summary: summarise, export: exportSessions, clear: clearSessions } };
