import type { Silhouette } from '../content/types';

/**
 * How each kind of unit moves.
 *
 * A rider gallops, a spearman marches, an archer draws and looses. The
 * simulation does not know or care about any of this — it emits positions and
 * attack events, and everything here is presentation layered on top. That
 * separation is what keeps online play in lockstep: two clients can animate
 * differently and still agree on the result.
 *
 * These profiles are tuned to the placeholder silhouettes. When the commissioned
 * character art lands, the art changes and the profiles stay — a horse still
 * gallops whoever drew it.
 */

export type AttackStyle = 'thrust' | 'swing' | 'shoot' | 'charge' | 'stomp' | 'lash';

export interface MotionProfile {
  /** Bounce along the direction of travel. Gait, essentially. */
  bobAmp: number;
  bobHz: number;
  /** Side-to-side roll. */
  swayAmp: number;
  swayHz: number;
  /** Body lean, in radians. */
  tiltAmp: number;
  tiltHz: number;
  /** Feet leave the ground — a gallop, not a march. */
  airborne: boolean;
  attack: AttackStyle;
  /** Ranged units throw something visible. */
  projectile?: { kind: 'arrow' | 'stone'; speed: number };
}

const MARCH: MotionProfile = {
  bobAmp: 1.6, bobHz: 3.4, swayAmp: 0.5, swayHz: 1.7, tiltAmp: 0.03, tiltHz: 3.4,
  airborne: false, attack: 'thrust',
};

const PROFILES: Record<Silhouette, MotionProfile> = {
  // Foot. A steady tramp, and a straight thrust of the spear.
  spear: MARCH,

  // The shield wall moves slower and heavier, and shoves rather than stabs.
  shield: {
    bobAmp: 1.1, bobHz: 2.4, swayAmp: 0.9, swayHz: 1.2, tiltAmp: 0.02, tiltHz: 2.4,
    airborne: false, attack: 'thrust',
  },

  // Archers barely move: they are here to stand still and shoot.
  bow: {
    bobAmp: 0.7, bobHz: 2.2, swayAmp: 0.3, swayHz: 1.1, tiltAmp: 0.015, tiltHz: 2.2,
    airborne: false, attack: 'shoot',
    projectile: { kind: 'arrow', speed: 210 },
  },

  // A gallop: big vertical throw, real airtime, body leaning into the run.
  horse: {
    bobAmp: 4.2, bobHz: 5.2, swayAmp: 1.1, swayHz: 2.6, tiltAmp: 0.12, tiltHz: 5.2,
    airborne: true, attack: 'charge',
  },

  // Same gait, but the rider is turned in the saddle shooting.
  'horse-bow': {
    bobAmp: 3.8, bobHz: 5.0, swayAmp: 1.3, swayHz: 2.5, tiltAmp: 0.1, tiltHz: 5.0,
    airborne: true, attack: 'shoot',
    projectile: { kind: 'arrow', speed: 200 },
  },

  // Camels lope — slower cadence, much more roll than a horse.
  camel: {
    bobAmp: 3.0, bobHz: 3.0, swayAmp: 2.6, swayHz: 1.5, tiltAmp: 0.09, tiltHz: 3.0,
    airborne: false, attack: 'shoot',
    projectile: { kind: 'arrow', speed: 185 },
  },

  // Wheels do not bounce. It rolls flat and fast, and hits by running through.
  chariot: {
    bobAmp: 0.9, bobHz: 7.5, swayAmp: 0.6, swayHz: 3.4, tiltAmp: 0.05, tiltHz: 7.5,
    airborne: false, attack: 'charge',
  },

  // Enormous and slow: a long sway and a stamp.
  elephant: {
    bobAmp: 2.0, bobHz: 1.5, swayAmp: 3.0, swayHz: 0.75, tiltAmp: 0.05, tiltHz: 1.5,
    airborne: false, attack: 'stomp',
  },

  // Club-armed foot: marches, then swings overhead.
  club: { ...MARCH, attack: 'swing' },

  // Rides like cavalry, but the kill is a thrown noose.
  lasso: {
    bobAmp: 3.6, bobHz: 4.8, swayAmp: 1.4, swayHz: 2.4, tiltAmp: 0.11, tiltHz: 4.8,
    airborne: true, attack: 'lash',
  },
};

export function motionFor(s: Silhouette): MotionProfile {
  return PROFILES[s] ?? MARCH;
}

/**
 * Gait offsets for a unit at time `t`, phase-shifted per unit so a rank does not
 * move as one body.
 */
export function gait(
  p: MotionProfile,
  t: number,
  phase: number,
  moving: boolean,
): { bob: number; sway: number; tilt: number } {
  // Standing units keep a small idle breath so the field never looks frozen.
  const scale = moving ? 1 : 0.25;
  const w = (hz: number) => (t * hz + phase) * Math.PI * 2;
  // An airborne gait spends longer off the ground than on it, so the bounce is
  // rectified rather than a plain sine.
  const bobWave = p.airborne ? Math.abs(Math.sin(w(p.bobHz) / 2)) - 0.4 : Math.sin(w(p.bobHz));
  return {
    bob: bobWave * p.bobAmp * scale,
    sway: Math.sin(w(p.swayHz)) * p.swayAmp * scale,
    tilt: Math.sin(w(p.tiltHz)) * p.tiltAmp * scale,
  };
}

/**
 * Local height of a sprite before the board's scale is applied.
 *
 * Here rather than in `BattleCanvas` because the layout test needs the same
 * number, and it used to hold its own copy of this and of `unitScale` — the
 * exact weakness that file's own header warns about.
 */
export const SPRITE_HEIGHT = 38;

/**
 * How big a man is drawn on a board this wide.
 *
 * Was `w / 520`, which held a man at about 7.3% of the board's width — measured
 * off the reference game's recording, an 80px body against an 1100px board.
 * That proportion is right for a board that FILLS a screen and wrong for the
 * one this game actually draws: on a desktop the field is a portrait panel in
 * the middle of the window, so 7.3% of it came out at 28 physical pixels, and
 * at 28px a painted soldier is a smudge with a colour. Reported from play as
 * figures that "are not recognisable" and "bump into each other".
 *
 * So the proportion is deliberately above the reference now — about 9% — and
 * the board itself is allowed to grow wider on a desktop, which is where the
 * rest of the size comes from.
 */
export function unitScale(w: number): number {
  return Math.max(0.7, Math.min(1.85, w / 430));
}

/** Closest the battle camera pulls in. Past this a melee outgrows the board. */
export const MAX_CAMERA_ZOOM = 1.9;

/**
 * How big a man is drawn, board width and camera together.
 *
 * The SQUARE ROOT of the zoom, not the zoom: folding it in one-for-one made
 * closing the view pointless, because the field spread and the bodies inflated
 * by the same amount and the knot of fighting men stayed exactly as large a
 * fraction of the board. Under a root the distances open faster than the
 * figures do.
 */
export function figureScale(w: number, zoom = 1): number {
  return unitScale(w) * Math.sqrt(zoom);
}

/**
 * Attack pose at `k` (0 → 1 through the swing). Returns a lunge along the facing
 * axis and a rotation, both of which peak early and recover — a strike is fast
 * out and slow back.
 *
 * The lunge is in SPRITE-LOCAL pixels: the caller multiplies by the board's
 * scale, or a blow that reads on a phone disappears on a desktop, which is
 * precisely what it used to do.
 */
export function attackPose(style: AttackStyle, k: number): { lunge: number; spin: number } {
  const snap = k < 0.3 ? k / 0.3 : 1 - (k - 0.3) / 0.7;
  switch (style) {
    // Half again on every one of these, because a blow has to travel far enough
    // to be seen as a blow. A spearman moving 7px on a 38px body is a man
    // leaning; 11px is a man putting his weight behind a thrust.
    case 'thrust':
      return { lunge: snap * 11, spin: snap * 0.1 };
    case 'swing':
      return { lunge: snap * 5, spin: -snap * 1.15 };
    case 'charge':
      return { lunge: snap * 17, spin: snap * 0.2 };
    case 'stomp':
      return { lunge: snap * 6, spin: 0 };
    case 'lash':
      return { lunge: snap * 7, spin: snap * 0.62 };
    case 'shoot':
      // Recoil backwards rather than lunging forward.
      return { lunge: -snap * 5, spin: 0 };
  }
}


/**
 * Attack timing against the log.
 *
 * The simulation deducts health and emits its attack event on the same tick.
 * The renderer used to treat that as the cue to START everything — recoil,
 * flash, and the launch of an arrow that then had to fly — so a man fell before
 * the arrow reached him. The log is fully precomputed, so the renderer can work
 * BACKWARDS from each impact instead: launch early enough to arrive on time.
 *
 * Speeds are in FIELD units per tick rather than screen pixels per second, so
 * the lead is identical on any canvas and at any playback speed.
 */
export const PROJECTILE_FIELD_SPEED = 5.5;

/**
 * Never lead by more than this. A lead longer than the attack interval would
 * launch the next arrow before the previous one had landed, and the screen
 * would fill with shots that belong to hits already scored.
 */
export const MAX_LEAD_TICKS = 10;

/**
 * `attackPose` peaks about a third of the way through its life, so a swing
 * begun ON the impact peaks after it. Starting this early puts the peak on the
 * blow.
 */
export const SWING_LEAD_TICKS = 2;

/** Ticks to launch a projectile ahead of its logged impact, given the gap in field units. */
export function projectileLeadTicks(gapFieldUnits: number): number {
  const gap = Math.max(0, gapFieldUnits);
  return Math.min(MAX_LEAD_TICKS, Math.round(gap / PROJECTILE_FIELD_SPEED));
}

/**
 * The two clocks, and why there is only one left.
 *
 * The renderer has a wall clock — `ticker.deltaMS`, real seconds — and a
 * playback clock, the log's own ticks, which run at `TICK_RATE × speed`. The
 * combat has always been on the second one: positions, deaths and impacts all
 * come out of the log, so at 4× the fight advances four times as fast.
 *
 * Every GESTURE was on the first one. A swing took 0.34 real seconds whatever
 * speed you watched at, so at 4× a man was struck, staggered and killed while
 * the blow that did it was a third of the way through — and his legs cycled at
 * walking pace while he slid across the field at a run. The animation was not
 * slower than the combat; it was in a different time entirely.
 *
 * So gesture lifetimes are advanced by `playbackSeconds`, and the gait and the
 * rig stride read the playback clock rather than the wall clock. One clock, and
 * it is the log's: fast-forward now speeds up the whole picture, the way
 * fast-forwarding a recording does.
 */
export function playbackSeconds(dtSeconds: number, speed: number): number {
  return dtSeconds * Math.max(0, speed) * BATTLE_PACE;
}

/**
 * How fast a battle plays, against how fast the simulation ticks.
 *
 * The simulation reasons in ticks and the log is fixed; this only decides how
 * much WALL TIME one tick is given. At 1.0 the men crossed the field at a jog
 * and the march cadence came out at 3.4 steps a second, which is a run.
 *
 * At 0.7 a marching man takes about 2.4 steps a second — a real marching
 * cadence is around two — and a charge still reads as a charge because
 * everything keeps its relative timing.
 *
 * NOTHING ELSE NEEDS RETUNING, which is the reason it is one number here rather
 * than a pass over the constants. Every animation in the renderer is measured in
 * PLAYBACK seconds, and `elapsedTicks` is derived from the same function, so a
 * swing still spans 6.8 ticks and an arrow still lands on its logged tick
 * whatever the pace is. The pace dilates wall time and nothing else.
 *
 * The cost is honest and worth stating: a round takes 1/0.7 as long to watch,
 * which is dead time by the telemetry's own definition. The speed control gives
 * it straight back, and it is the player's to spend.
 */
export const BATTLE_PACE = 0.7;

/** The playback clock in seconds, from the tick count the log is being read at. */
export function playbackClock(elapsedTicks: number, tickRate: number): number {
  return elapsedTicks / tickRate;
}
