/**
 * What actually happens when somebody plays.
 *
 * Two outside reviews and every argument in this repo about pacing have run on
 * the same missing fact: nobody knows why a child stops playing. Round counts
 * are not session duration, "feels thin" is not a measurement, and a decision
 * about decision VOLUME cannot be judged by the person who designed the volume.
 *
 * So this records wall-clock facts and nothing else:
 *
 *   time to first pick   how long the first choice takes — the tutorial cost
 *   decision time        per round, how long a choice takes once they know how
 *   post-lock wait       from locking a pick to the next offer opening; the
 *                        dead time, which is the number a pacing complaint is
 *                        usually really about
 *   where it ends        the last screen and the last round before they left
 *
 * DELIBERATELY LOCAL. Nothing here transmits, and nothing here has a hook to
 * transmit from. This is a game for nine-year-olds: sending a child's session
 * timings anywhere is a decision with consent and data-protection weight behind
 * it, and it is not one to make as a side effect of wanting a number. Read it
 * off the device by hand — `window.persia.telemetry` — until that decision is
 * taken deliberately.
 *
 * It also records no content: no names, no scores, no picks by id. Durations,
 * round numbers and screen names, which is all the pacing question needs.
 */

const KEY = 'persia-at-war/telemetry/v1';
/** Sessions kept. Enough to see a habit; far short of a history. */
const MAX_SESSIONS = 30;
/** Events per session. A long sitting is interesting; an unbounded array is not. */
const MAX_EVENTS = 400;

export type TelemetryEvent =
  /** A screen was opened. `at` is milliseconds since the session started. */
  | { t: 'screen'; at: number; screen: string }
  /** A round's offer became choosable. `cards` is how many were on it. */
  | { t: 'offer'; at: number; round: number; cards: number }
  /** A choice landed. `thought` is how long the offer was up before it did. */
  | { t: 'pick'; at: number; round: number; thought: number }
  /** The next offer opened. `waited` is the dead time since the last pick. */
  | { t: 'resume'; at: number; round: number; waited: number }
  /** A match finished on its own terms. */
  | { t: 'matchEnd'; at: number; rounds: number; won: boolean }
  /** A match was left before it finished — the interesting kind of ending. */
  | { t: 'abandon'; at: number; round: number }
  /** The tab was hidden or closed. The session may resume after 'hidden'. */
  | { t: 'away'; at: number; screen: string };

export interface Session {
  id: string;
  /** Wall clock, so two sessions can be ordered. Everything else is relative. */
  startedAt: number;
  events: TelemetryEvent[];
}

function storage(): Storage | null {
  try {
    return typeof localStorage === 'undefined' ? null : localStorage;
  } catch {
    return null;
  }
}

export function loadSessions(): Session[] {
  const store = storage();
  if (!store) return [];
  try {
    const all = JSON.parse(store.getItem(KEY) ?? '[]') as Session[];
    return Array.isArray(all) ? all.filter((s) => s && Array.isArray(s.events)) : [];
  } catch {
    return [];
  }
}

/**
 * The live session.
 *
 * Module state rather than store state on purpose: this must not cause a React
 * render, and it must not end up in the save file. It is a side channel, and
 * the game must play identically with it ripped out.
 */
let current: Session | null = null;
let lastPickAt: number | null = null;
let offerShownAt: number | null = null;
let lastScreen = '';
let lastRound = 0;

function now(): number {
  return Date.now();
}

function since(): number {
  return current ? now() - current.startedAt : 0;
}

function persist(): void {
  const store = storage();
  if (!store || !current) return;
  const others = loadSessions().filter((s) => s.id !== current!.id);
  try {
    store.setItem(KEY, JSON.stringify([current, ...others].slice(0, MAX_SESSIONS)));
  } catch {
    // Quota or a hardened profile. Losing telemetry is free; letting it throw
    // into a click handler is not.
  }
}

function push(ev: TelemetryEvent): void {
  if (!current) return;
  // Past the cap the session stops recording rather than rolling, so what is
  // kept is a contiguous run from the start and not a window with a hole in it.
  if (current.events.length >= MAX_EVENTS) return;
  current.events.push(ev);
  persist();
}

/** Starts a session. Safe to call twice; the second call is ignored. */
export function beginSession(): void {
  if (current) return;
  current = {
    id: `${now().toString(36)}-${Math.floor(Math.random() * 1e6).toString(36)}`,
    startedAt: now(),
    events: [],
  };
  lastPickAt = null;
  offerShownAt = null;
  lastScreen = '';
  lastRound = 0;
}

export function trackScreen(screen: string): void {
  if (screen === lastScreen) return;
  lastScreen = screen;
  push({ t: 'screen', at: since(), screen });
}

/**
 * A round's offer is up.
 *
 * Also closes the previous round's dead time: the gap between locking a choice
 * and being asked for the next one is the only place a player is waiting on the
 * game rather than on themselves, so it is measured from the pick rather than
 * from the end of the battle.
 */
export function trackOffer(round: number, cards: number): void {
  if (!current) return;
  lastRound = round;
  const at = since();
  if (lastPickAt !== null) {
    push({ t: 'resume', at, round, waited: at - lastPickAt });
  }
  offerShownAt = at;
  push({ t: 'offer', at, round, cards });
}

export function trackPick(round: number): void {
  if (!current) return;
  const at = since();
  push({ t: 'pick', at, round, thought: offerShownAt === null ? 0 : at - offerShownAt });
  lastPickAt = at;
  offerShownAt = null;
}

export function trackMatchEnd(rounds: number, won: boolean): void {
  push({ t: 'matchEnd', at: since(), rounds, won });
  lastPickAt = null;
  offerShownAt = null;
  lastRound = 0;
}

/** Left a match before it resolved. The ending that a round count cannot see. */
export function trackAbandon(): void {
  if (lastRound === 0) return;
  push({ t: 'abandon', at: since(), round: lastRound });
  lastPickAt = null;
  offerShownAt = null;
  lastRound = 0;
}

/** The tab went away. Called from `pagehide`, which fires when a close does. */
export function trackAway(): void {
  push({ t: 'away', at: since(), screen: lastScreen });
}

/**
 * Wires the page-level ending.
 *
 * `pagehide` rather than `beforeunload`: it is the one that fires on mobile
 * Safari when an app is swiped away, which is exactly the session ending we
 * most want and the one `beforeunload` misses.
 */
export function watchPageEnd(): () => void {
  if (typeof window === 'undefined') return () => {};
  const onHide = () => trackAway();
  window.addEventListener('pagehide', onHide);
  return () => window.removeEventListener('pagehide', onHide);
}

// ------------------------------------------------------------------ the report

export interface Summary {
  sessions: number;
  /** Median session length in seconds, from first event to last. */
  medianSessionSec: number;
  /** Median time to the FIRST pick of a session, in seconds. */
  medianFirstPickSec: number;
  /** Median time to choose, in seconds, across every pick after the first. */
  medianDecisionSec: number;
  /** Median dead time between locking a pick and the next offer, in seconds. */
  medianWaitSec: number;
  /** Share of the session spent waiting rather than choosing or watching. */
  matchesFinished: number;
  matchesAbandoned: number;
  /** How far in a session gets before it ends, as a count per round reached. */
  endedAtRound: Record<number, number>;
  /** Last screen before the session ended, counted. */
  endedOn: Record<string, number>;
}

function median(xs: number[]): number {
  if (xs.length === 0) return 0;
  const s = [...xs].sort((a, b) => a - b);
  const mid = Math.floor(s.length / 2);
  return s.length % 2 ? s[mid] : (s[mid - 1] + s[mid]) / 2;
}

const sec = (ms: number): number => Math.round(ms / 100) / 10;

/**
 * Turns the sessions into the four numbers the pacing argument needs.
 *
 * Medians, not means. One session left open on a desk for an hour would move a
 * mean and would say nothing about how long anybody played.
 */
export function summarise(sessions: Session[] = loadSessions()): Summary {
  const lengths: number[] = [];
  const firstPicks: number[] = [];
  const decisions: number[] = [];
  const waits: number[] = [];
  const endedAtRound: Record<number, number> = {};
  const endedOn: Record<string, number> = {};
  let finished = 0;
  let abandoned = 0;

  for (const s of sessions) {
    if (s.events.length === 0) continue;
    lengths.push(s.events[s.events.length - 1].at);
    let seenPick = false;
    let lastRoundSeen = 0;
    for (const ev of s.events) {
      switch (ev.t) {
        case 'pick':
          if (seenPick) decisions.push(ev.thought);
          else {
            firstPicks.push(ev.thought);
            seenPick = true;
          }
          lastRoundSeen = ev.round;
          break;
        case 'resume':
          waits.push(ev.waited);
          break;
        case 'matchEnd':
          finished += 1;
          lastRoundSeen = 0;
          break;
        case 'abandon':
          abandoned += 1;
          lastRoundSeen = 0;
          break;
        default:
          break;
      }
    }
    // A session that stopped mid-match ended somewhere, and where is the point.
    if (lastRoundSeen > 0) endedAtRound[lastRoundSeen] = (endedAtRound[lastRoundSeen] ?? 0) + 1;
    const last = [...s.events].reverse().find((e) => e.t === 'screen' || e.t === 'away');
    const screen = last && 'screen' in last ? last.screen : 'unknown';
    endedOn[screen] = (endedOn[screen] ?? 0) + 1;
  }

  return {
    sessions: sessions.filter((s) => s.events.length > 0).length,
    medianSessionSec: sec(median(lengths)),
    medianFirstPickSec: sec(median(firstPicks)),
    medianDecisionSec: sec(median(decisions)),
    medianWaitSec: sec(median(waits)),
    matchesFinished: finished,
    matchesAbandoned: abandoned,
    endedAtRound,
    endedOn,
  };
}

/** Everything, as JSON, for getting it off a device by hand. */
export function exportSessions(): string {
  return JSON.stringify(loadSessions(), null, 2);
}

/**
 * Forgets everything and starts recording again.
 *
 * The restart is the point. Dropping the session as well as the store was the
 * first version, and it made the tool useless in the way it is actually used —
 * clear, play for ten minutes, read the summary, get nothing, because clearing
 * had also switched the recorder off. Found by doing exactly that.
 */
export function clearSessions(): void {
  const store = storage();
  current = null;
  try {
    store?.removeItem(KEY);
  } catch {
    // Nothing to do and nothing worth throwing over.
  }
  beginSession();
}

/** For tests: the live session, or null. */
export function currentSession(): Session | null {
  return current;
}
