import { useEffect, useRef } from 'react';
import { Application, Assets, ColorMatrixFilter, Container, Graphics, Sprite, Texture } from 'pixi.js';
import type { Battle, Silhouette } from '../content/types';
import { getArena } from '../content';
import type { BattleLog } from '../sim/types';
import { FIELD_MAX, FIELD_MIN, TICK_RATE } from '../sim/types';
import { themeFor } from '../ui/arenaTheme';
import {
  SWING_LEAD_TICKS,
  attackPose,
  gait,
  motionFor,
  playbackClock,
  playbackSeconds,
  projectileLeadTicks,
  MAX_CAMERA_ZOOM,
  SPRITE_HEIGHT,
  figureScale,
} from './motion';
import { PALETTE, drawSilhouette } from './silhouettes';
import {
  addTrauma,
  approach,
  arcHeight,
  arcPoint,
  cheer,
  closeGap,
  decayTrauma,
  engagedX,
  facing,
  grade,
  hash01,
  lineOfSquads,
  requestHitStop,
  separate,
  shakeOffset,
  spawn,
  squadSlot,
  stepHitStop,
  stepParticles,
  type HitStop,
  type Particle,
} from './feel';
import { rigDef, rigUrls, unitArtUrl } from './unitArt';
import {
  applyPose,
  asRigDef,
  buildRig,
  gallop,
  idle,
  isMounted,
  march,
  partsOf,
  type RigPart,
  type RiggedFigure,
} from './rig';

const SIDE_COLOR = { a: PALETTE.red, b: PALETTE.blue } as const;
const SIDE_TRIM = { a: PALETTE.gold, b: PALETTE.white } as const;
/** Seconds an attack streak or a strike flare stays on screen. */
const FLASH_LIFE = 0.2;

/** Seconds a unit spends in its attack pose. */
const SWING_LIFE = 0.34;
/**
 * How long a struck unit reacts for.
 *
 * The attacker had a swing and the hit had a flare, but the VICTIM did nothing —
 * so a blow landed on a figure that went on breathing as though nothing had
 * touched it, and the whole exchange read as decoration rather than damage.
 * Short on purpose: long enough to see, too short to fight the gait.
 */
const HURT_LIFE = 0.34;
/**
 * How hard a hit throws a man back, in screen pixels.
 *
 * A blow that a body does not answer reads as a number changing, not as a
 * fight. He gives ground, staggers off his line, and walks back into it — the
 * recovery is what makes it a stagger rather than a teleport.
 */
const KNOCKBACK = 9;
const STAGGER = 4.5;
/** How long a man takes to fall over once killed. */
const FALL_LIFE = 0.55;

/*
 * GAME FEEL — see feel.ts for what each of these does and why.
 */
/** How quickly a man moves sideways to where he wants to stand, per second. */
const STEER_X_RATE = 5;
/** How tightly he follows the battle log along the field. Fast, or he lags the fight. */
const STEER_Y_RATE = 16;
/** Ticks after his last blow that a man still counts as engaged with his opponent. */
const ENGAGE_TICKS = 30;
/** The furthest a melee man closes along the field to make contact, in unscaled px. */
const MAX_CLOSE = 22;
/**
 * How far sideways a man will step toward his opponent, in body widths, and how
 * far away an opponent can be before he stops stepping at all.
 *
 * Both limits exist because of the same measurement. With a pull of 2.2 body
 * widths, a man moved 2.2 toward his enemy and the enemy moved 2.2 back, so any
 * pair within 4.4 collapsed onto each other — and then their neighbours
 * collapsed onto them. Measured in a round-6 fight: by tick 300 the survivors'
 * FORMATION still spanned 6.6 body widths while the men were drawn across 2.5.
 * The army was a ball with a line's worth of room around it.
 *
 * A man now shuffles a little to face who he is fighting, and a man whose
 * nearest enemy is right across the field holds his place in the line instead
 * of setting off after him. Closing the distance is the simulation's job, and
 * it is already doing it along the field.
 */
const SIDESTEP = 1.2;
const SIDESTEP_REACH = 5;
/** Camera shake at full trauma, in px, and how fast trauma bleeds away per second. */
const SHAKE_PX = 7;
const TRAUMA_DECAY = 2.2;
/** Dust is the arena's own sand, not grey smoke. */
const DUST = 0xc9ad84;
/** What a fallen man is tinted, so the living stand out from the field of the dead. */
const CORPSE_TINT = 0x9c9184;

const hex = (s: string): number => Number.parseInt(s.replace('#', ''), 16);
/*
 * SPRITE_HEIGHT and unitScale live in `motion.ts` now, so the renderer and the
 * layout test read one definition instead of two copies of a number.
 */

/** Idle sway, in radians. A standing man is never perfectly still. */
const WIND_TILT = 0.055;
const WIND_SPEED = 0.075;

interface Props {
  log: BattleLog;
  battle: Battle;
  /** The ladder rung being fought on — decides the floor. */
  arenaId: number;
  speed: number;
  /** Fires once, when playback reaches the end of the log. */
  onFinished: () => void;
}

interface Flash {
  from: number;
  to: number;
  mult: number;
  life: number;
}

/** A commander's order firing. One a match, so it gets a ring of its own. */
interface OrderBurst {
  uid: number;
  life: number;
}
const ORDER_LIFE = 1.1;

interface Shot {
  /** Who it is aimed at, so it lands on them and not on where they were. */
  toUid: number;
  /** Playback ticks, not seconds: a projectile must arrive on its logged tick
   *  whatever speed the player is watching at. */
  startTick: number;
  endTick: number;
  fromX: number;
  fromY: number;
  toX: number;
  toY: number;
  kind: 'arrow' | 'stone';
}

/**
 * The battlefield.
 *
 * **Portrait, and the player is at the bottom.** The simulation is
 * one-dimensional — every unit has a single "advance" coordinate — so rotating
 * the field is purely a rendering decision: the same deterministic log is mapped
 * down the screen instead of across it. Nothing in `sim/` changed, which is what
 * keeps two online clients agreeing on the result while drawing it differently.
 *
 * The view is the arena floor seen from above, not a landscape with a horizon.
 * Two ranks face each other along the length of the phone and close on the
 * middle, each unit moving the way its own kind moves — see `motion.ts`.
 */
export function BattleCanvas({ log, battle, arenaId, speed, onFinished }: Props) {
  const hostRef = useRef<HTMLDivElement>(null);
  // Read through refs so changing speed doesn't tear down and rebuild the canvas.
  const speedRef = useRef(speed);
  const finishedRef = useRef(false);
  const onFinishedRef = useRef(onFinished);
  speedRef.current = speed;
  onFinishedRef.current = onFinished;

  useEffect(() => {
    const host = hostRef.current;
    if (!host) return;

    let destroyed = false;
    let app: Application | null = null;
    let observer: ResizeObserver | null = null;
    finishedRef.current = false;

    const hostSize = (): { w: number; h: number } => {
      const r = host.getBoundingClientRect();
      // The host can measure 0 before first layout; never hand Pixi a zero size.
      return { w: Math.max(1, Math.round(r.width)), h: Math.max(1, Math.round(r.height)) };
    };

    void (async () => {
      const instance = new Application();
      const initial = hostSize();
      await instance.init({
        backgroundAlpha: 0,
        antialias: true,
        resolution: Math.min(window.devicePixelRatio || 1, 2),
        autoDensity: true,
        width: initial.w,
        height: initial.h,
      });
      if (destroyed) {
        instance.destroy(true, { children: true });
        return;
      }
      app = instance;
      host.replaceChildren(instance.canvas);
      // Dev only: lets a harness step the ticker by hand and photograph frames.
      // Motion cannot be checked from a single screenshot, and an in-app
      // browser pauses animation while a script runs — so the check steps time
      // itself. Stripped from production builds by the DEV guard.
      if (import.meta.env.DEV) {
        (window as unknown as { __battle?: unknown }).__battle = { app: instance };
      }

      observer = new ResizeObserver(() => {
        const { w, h } = hostSize();
        if (w !== instance.screen.width || h !== instance.screen.height) instance.renderer.resize(w, h);
      });
      observer.observe(host);

      const ground = new Graphics();
      const shotLayer = new Graphics();
      const flashLayer = new Graphics();
      /*
       * Layers, back to front: floor, shadows, the dead, dust, the living,
       * arrows, sparks, flares. The dead get a layer of their own so a man who
       * falls stays on the field — an aftermath is most of what makes a fight
       * look like it happened — without ever being drawn over someone alive.
       */
      const shadowLayer = new Graphics();
      const corpseLayer = new Container();
      const dustLayer = new Graphics();
      const unitLayer = new Container();
      // Sorted by screen y every frame, so once men leave their columns and mix
      // into a melee, the man nearer the viewer is the one drawn in front.
      unitLayer.sortableChildren = true;
      /*
       * The living are lifted off the floor by COLOUR, not just by position.
       *
       * Measured: 98.9% of the board's pixels sat in one hue band and nothing
       * was brighter than 40% grey, so brown men stood on brown ground at the
       * same brightness and read as shadows. One filter on the whole layer —
       * not one per man — brightens and saturates every living figure, which is
       * the cheapest way to put the men in front of the arena instead of in it.
       *
       * Deliberately NOT applied to the corpse layer: the dead staying dull is
       * what makes the living read as the thing to watch.
       */
      const alive = new ColorMatrixFilter();
      alive.brightness(1.22, false);
      alive.saturate(0.34, true);
      unitLayer.filters = [alive];
      const sparkLayer = new Graphics();
      /*
       * Squad health bars, drawn over the squad's middle rather than hanging off
       * one man. Carried by the lowest-file survivor, every bar sat on the
       * squad's LEFT edge, and once squads mixed into a melee four bars stacked
       * in one corner of it and could not be told apart.
       */
      const barLayer = new Graphics();
      // Everything the camera moves. Shake moves the world, not the page.
      const world = new Container();
      world.addChild(ground, shadowLayer, corpseLayer, dustLayer, unitLayer, shotLayer, sparkLayer, flashLayer, barLayer);
      instance.stage.addChild(world);

      const theme = themeFor(getArena(arenaId).slug);
      const accent = hex(theme.accent);
      // The floor is the LIGHTER token and the surround the darkest, so the
      // fighting ground separates from what encloses it. The other way round
      // the two read as one flat slab.
      /*
       * The fighting floor is graded DOWN so the men can sit on top of it.
       *
       * Darkened and partly desaturated rather than recoloured: each arena's
       * floor colour is its identity — Anshan is sand, Babylon glazed blue —
       * and turning every floor to cold slate would buy separation by throwing
       * away the promise that the world changes as you climb.
       */
      // `floor`, not `surface`: the panels are cooled toward lapis and the
      // fighting ground is not. Anshan's floor stays sand.
      const floor = grade(hex(theme.floor), 0.62, 0.78);
      const floorDeep = hex(theme.floorDeep);
      const rim = hex(theme.rimLight);

      /**
       * Commissioned art is a texture; a unit still waiting for art is the old
       * vector shape. Both are Containers, so everything downstream — the gait,
       * the lunge, the death spin — is identical either way.
       */
      const artUrls = [...new Set(log.roster.map((u) => unitArtUrl(u.defId)))].filter(
        (u): u is string => u !== null,
      );
      const textures = new Map<string, Texture>();
      // Rig parts, keyed `unitId/part`. Loaded with the sprites so a rigged
      // unit never pops in a frame later than an unrigged one.
      const rigTex = new Map<string, Texture>();
      // Rig parts for whichever units on this field are rigged.
      const rigJobs: { key: string; url: string }[] = [];
      for (const id of new Set(log.roster.map((u) => u.defId))) {
        const parts = rigUrls(id);
        if (!parts) continue;
        for (const [part, url] of Object.entries(parts)) rigJobs.push({ key: `${id}/${part}`, url });
      }
      if (artUrls.length > 0 || rigJobs.length > 0) {
        const [loaded, rigLoaded] = await Promise.all([
          Promise.all(artUrls.map((u) => Assets.load<Texture>(u))),
          Promise.all(rigJobs.map((j) => Assets.load<Texture>(j.url))),
        ]);
        artUrls.forEach((u, i) => textures.set(u, loaded[i]));
        rigJobs.forEach((j, i) => rigTex.set(j.key, rigLoaded[i]));
        if (destroyed) {
          instance.destroy(true, { children: true });
          return;
        }
      }

      interface Piece {
        root: Container;
        body: Container;
        bar: Graphics;
        silhouette: Silhouette;
        phase: number;
        /** Counts down while the unit is mid-swing. */
        swing: number;
        /** Counts down while the unit is recoiling from a hit. */
        hurt: number;
        /** True when this unit is commissioned art rather than a placeholder. */
        tall: boolean;
        /** This man's uid, so his swing hand is stable across frames. */
        uid: number;
        /** Counts down while he is falling. */
        fall: number;
        /** Present only for a rigged unit — the parts to pose each frame. */
        rig: RiggedFigure | null;
        /** Whether this rig gallops or marches. */
        mounted: boolean;
        /** The team ring under his feet, so it can stay on the ground when he bobs. */
        ring: Graphics;
        /** Ring radius in unscaled px, which his shadow is sized from. */
        ringRx: number;
        /** Where he is actually drawn — steered and smoothed, not the raw log. NaN until placed. */
        sx: number;
        sy: number;
        /** His logged screen y this frame, for opponents closing the gap to him. */
        baseY: number;
        /** Who he is fighting, or -1. */
        target: number;
        /** Tick of his last blow given or taken — or of a swing being wound up. */
        lastHitTick: number;
        /**
         * Tick of the last blow he actually LANDED. Separate from lastHitTick on
         * purpose: the swing starts two ticks before the blow and marks him
         * engaged, so reading lastHitTick at the impact said every charge had
         * already arrived and no charge ever shook the camera. Measured: trauma
         * 0.00 through a cavalry charge into a line.
         */
        lastImpactTick: number;
        /** Fallen, finished falling, and moved to the corpse layer. */
        corpse: boolean;
        /** Seconds until he kicks up the next puff of dust. */
        dustT: number;
        /** Which rank of his squad's block he stands in. 0 is the front. */
        rank: number;
        /** Where his formation puts him, before any steering. */
        homeX: number;
        /** 1 faces right, -1 faces left. The art is painted facing right. */
        face: 1 | -1;
        /** Screen x of whoever he is turned toward, or NaN when nobody. */
        faceAt: number;
      }

      const sprites = new Map<number, Piece>();
      for (const u of log.roster) {
        const root = new Container();

        const url = unitArtUrl(u.defId);
        const texture = url ? textures.get(url) : undefined;
        // The ring has to match whatever it sits under: a horseman is half again
        // as wide as an archer, and one fixed ellipse looks wrong beneath both.
        let ringRx = 9;
        /**
         * A rigged unit is a container of parts on pivots; everything else is
         * one sprite. Both are Containers, so the gait, the lunge, the recoil
         * and the fall downstream do not know or care which they got.
         */
        const rigParts = rigUrls(u.defId);
        let rig: RiggedFigure | null = null;
        // Mounted rigs gallop, men on foot march. Read off the rig's own parts
        // rather than the silhouette, so a rig and its clip cannot disagree.
        let mounted = true;

        const makeBody = (): Container => {
          if (rigParts) {
            // Pivots come from this unit's own rig.json — see asRigDef.
            const def = asRigDef(rigDef(u.defId));
            const want = partsOf(def);
            const tex = Object.fromEntries(
              want.map((part) => [part, rigTex.get(`${u.defId}/${part}`)]),
            ) as Partial<Record<RigPart, Texture>>;
            if (want.every((part) => tex[part])) {
              mounted = isMounted(def);
              const built = buildRig(def, tex);
              rig = built;
              // The rig is drawn in texture pixels, so scale it to the same
              // height a plain sprite gets and hang it from the same foot line.
              const k = SPRITE_HEIGHT / def.size[1];
              const holder = new Container();
              holder.addChild(built.root);
              holder.scale.set(k);
              holder.position.set((-def.size[0] / 2) * k, -SPRITE_HEIGHT * 0.94);
              ringRx = Math.max(7, def.size[0] * k * 0.42);
              return holder;
            }
          }
          if (texture) {
            const art = new Sprite(texture);
            // Feet essentially on the origin, with a sliver below so the figure
            // meets the ground rather than hovering over it.
            art.anchor.set(0.5, 0.94);
            art.height = SPRITE_HEIGHT;
            art.width = (texture.width / texture.height) * SPRITE_HEIGHT;
            ringRx = Math.max(7, art.width * 0.42);
            return art;
          }
          const shape = new Graphics();
          drawSilhouette(shape, u.silhouette, SIDE_COLOR[u.side], SIDE_TRIM[u.side]);
          return shape;
        };

        /*
         * One sprite per MAN, because the simulation now emits one entry per
         * man. The cosmetic file-drawing this replaced is gone: a rank of
         * clones sharing one HP pool moved as a slab, and every figure here now
         * has its own position, its own target and its own death.
         */
        const body = makeBody();
        // Men further back sit fractionally smaller and dimmer, which reads as
        // depth without a second camera or a real z axis.
        const depth = 1 - Math.min(0.16, u.file * 0.03);
        // MULTIPLY, never assign. Setting `.height` on a Pixi Sprite works by
        // writing `.scale`, so `scale.set(depth)` throws that away and the man
        // snaps back to the texture's native 2048px. It filled the whole board.
        body.scale.set(body.scale.x * depth, body.scale.y * depth);
        body.alpha = 1 - Math.min(0.2, u.file * 0.04);

        // The team is read off a coloured ring on the ground, not off the unit.
        // Tinting full-colour art muddies it, and two armies of muddy figures is
        // worse than no team colour at all.
        const ringY = texture ? 1 : 13;
        const ring = new Graphics();
        // The one piece of saturated team colour every man carries. Stronger
        // than it was: at this size the ring does more work telling the sides
        // apart than anything painted on the figure.
        ring
          .ellipse(0, ringY, ringRx * 1.06, ringRx * 0.38)
          .fill({ color: SIDE_COLOR[u.side], alpha: 0.85 });
        ring
          .ellipse(0, ringY, ringRx * 1.06, ringRx * 0.38)
          .stroke({ width: 1.4, color: SIDE_TRIM[u.side], alpha: 0.9 });

        const bar = new Graphics();
        root.addChild(ring, body, bar);
        unitLayer.addChild(root);
        sprites.set(u.uid, {
          root,
          body,
          bar,
          silhouette: u.silhouette,
          // Phase-shift per MAN so a rank does not move as one body — this is
          // the single biggest reason a mass looks alive rather than stamped.
          phase: (u.uid * 0.37 + u.file * 0.29) % 1,
          swing: 0,
          hurt: 0,
          fall: 0,
          rig,
          mounted,
          uid: u.uid,
          tall: Boolean(texture),
          ring,
          ringRx,
          sx: Number.NaN,
          sy: Number.NaN,
          baseY: Number.NaN,
          target: -1,
          lastHitTick: -1e9,
          lastImpactTick: -1e9,
          corpse: false,
          dustT: 0,
          rank: 0,
          homeX: Number.NaN,
          face: 1,
          faceAt: Number.NaN,
        });
      }

      // Roster by uid, so a frame entry can find the man it belongs to.
      const byUid = new Map(log.roster.map((r) => [r.uid, r]));

      /**
       * Where each man stands across the width of the board.
       *
       * Replaces the per-squad LANE. The reference game packs its whole army
       * into a block along the baseline, four rows deep across the full width,
       * and that is most of why it reads as an army rather than as a diagram of
       * one: a lane gives each squad a private column, and six private columns
       * is a chart. Measured off the recording, its men sit about 0.85 of a body
       * width apart, overlapping slightly.
       *
       * A squad's DEPTH still comes from the simulation — squads spawn three
       * field units apart, which is roughly half a body height on screen, so
       * they stack into rows on their own without the renderer inventing any.
       */
      const squadSize = new Map<string, number>();
      const ordinal = new Map<number, number>();
      for (const r of log.roster) {
        const n = squadSize.get(r.squad) ?? 0;
        ordinal.set(r.uid, n);
        squadSize.set(r.squad, n + 1);
      }
      /*
       * Each side's squads in draft order — `${side}:${index}` — so they can be
       * laid out as a LINE rather than all centred on the same spot.
       */
      const sideSquads: Record<'a' | 'b', { id: string; men: number }[]> = { a: [], b: [] };
      for (const [id, men] of squadSize) {
        const side = id.startsWith('a:') ? 'a' : 'b';
        sideSquads[side].push({ id, men });
      }
      for (const side of ['a', 'b'] as const) {
        sideSquads[side].sort((x, y) => Number(x.id.split(':')[1]) - Number(y.id.split(':')[1]));
      }
      /** The line, recomputed only when the board is resized. */
      let linePlan: Record<'a' | 'b', Map<string, { centre: number; width: number }>> | null = null;
      let planWidth = -1;

      /*
       * Every attack, scheduled BACKWARDS from its logged impact.
       *
       * Walked once when the log arrives. For a ranged attacker the arrow's
       * flight time is derived from the distance in FIELD units at the moment
       * of the shot, so it is launched that many ticks early and lands on the
       * tick the simulation says it lands. For everyone the swing starts a
       * couple of ticks early, because attackPose peaks a third of the way in
       * and a swing begun on impact peaks after it.
       */
      interface Planned {
        atTick: number;
        eventTick: number;
        from: number;
        to: number;
        projectile: { kind: 'arrow' | 'stone' } | null;
        swing: boolean;
      }
      const planned = new Map<number, Planned[]>();
      const addPlan = (tick: number, plan: Planned): void => {
        const at = Math.max(0, tick);
        const list = planned.get(at);
        if (list) list.push(plan);
        else planned.set(at, [plan]);
      };
      for (let f = 0; f < log.frames.length; f++) {
        const posAt = new Map(log.frames[f].pos.map((q) => [q.uid, q.x]));
        for (const ev of log.frames[f].events) {
          if (ev.t !== 'attack') continue;
          const meta = byUid.get(ev.uid);
          const proj = meta ? motionFor(meta.silhouette).projectile : undefined;
          if (proj) {
            const gap = Math.abs((posAt.get(ev.target) ?? 0) - (posAt.get(ev.uid) ?? 0));
            const lead = projectileLeadTicks(gap);
            addPlan(f - lead, {
              atTick: f - lead, eventTick: f, from: ev.uid, to: ev.target,
              projectile: { kind: proj.kind }, swing: false,
            });
          }
          addPlan(f - SWING_LEAD_TICKS, {
            atTick: f - SWING_LEAD_TICKS, eventTick: f, from: ev.uid, to: ev.target,
            projectile: null, swing: true,
          });
        }
      }

      const flashes: Flash[] = [];
      const shots: Shot[] = [];
      const bursts: OrderBurst[] = [];
      let elapsedTicks = 0;
      let lastAppliedFrame = -1;
      let lastPlanFrame = -1;
      const particles: Particle[] = [];
      let trauma = 0;
      let hitStop: HitStop = { left: 0, cooldown: 0 };
      /** Real seconds, for the shake's tremor. Deliberately not the playback clock. */
      let realClock = 0;
      /** The log frame that last shook the camera for a charge. */
      let chargeShookAt = -1;
      /** Playback seconds since the round was decided. */
      let cheerT = 0;

      /** A spray of sparks off a blow. Scattered from a hash, so a replay sprays the same. */
      const sparks = (x: number, y: number, n: number, color: number, seed: number): void => {
        for (let i = 0; i < n; i++) {
          const ang = hash01(seed, i) * Math.PI * 2;
          const sp = 70 + hash01(seed, i, 1) * 110;
          const life = 0.22 + hash01(seed, i, 2) * 0.16;
          spawn(particles, {
            kind: 'spark', x, y,
            vx: Math.cos(ang) * sp, vy: Math.sin(ang) * sp - 60,
            life, max: life, size: 1.6, color,
          });
        }
      };
      /** A puff of the arena's sand, from feet or from a man hitting the ground. */
      const puff = (x: number, y: number, n: number, spread: number, seed: number): void => {
        for (let i = 0; i < n; i++) {
          const ang = hash01(seed, i, 3) * Math.PI * 2;
          const sp = spread * (0.4 + hash01(seed, i, 4) * 0.6);
          const life = 0.45 + hash01(seed, i, 5) * 0.35;
          spawn(particles, {
            kind: 'dust', x, y,
            vx: Math.cos(ang) * sp, vy: Math.sin(ang) * sp * 0.45,
            life, max: life, size: 2.5 + hash01(seed, i, 6) * 2.5, color: DUST,
          });
        }
      };

      /*
       * THE CAMERA.
       *
       * The field is a hundred units deep and a fight happens in about twelve
       * of them. Drawn at a fixed mapping, two armies spend the approach at
       * opposite edges — which is right — and then the whole battle collapses
       * into a knot in the middle of a mostly empty board, which is what it
       * looked like in play: small figures piling into each other with three
       * quarters of the field showing nothing.
       *
       * So the view follows the fight. The window is the living men plus a
       * margin, it never zooms past `MAX_ZOOM`, and it eases rather than snaps,
       * because a camera that tracks exactly is a camera that shakes.
       *
       * It is a VIEW, not a rule: it moves where men are drawn and how big they
       * are drawn, and touches nothing the simulation or the log knows about.
       */
      const FIELD_SPAN = FIELD_MAX - FIELD_MIN;
      /** Closest the view will pull in. Shared with the layout test. */
      const MAX_ZOOM = MAX_CAMERA_ZOOM;
      /** Field units of air kept around the men, so nobody fights on the rim. */
      const CAM_MARGIN = 9;
      let camLo = FIELD_MIN;
      let camHi = FIELD_MAX;

      const aimCamera = (lo: number, hi: number, dt: number): void => {
        let wantLo = lo - CAM_MARGIN;
        let wantHi = hi + CAM_MARGIN;
        const span = Math.max(wantHi - wantLo, FIELD_SPAN / MAX_ZOOM);
        const mid = (wantLo + wantHi) / 2;
        wantLo = mid - span / 2;
        wantHi = mid + span / 2;
        // Slid back inside the field rather than clipped, so the window keeps
        // its span and a fight near the baseline is not half off the board.
        if (wantLo < FIELD_MIN) {
          wantHi += FIELD_MIN - wantLo;
          wantLo = FIELD_MIN;
        }
        if (wantHi > FIELD_MAX) {
          wantLo -= wantHi - FIELD_MAX;
          wantHi = FIELD_MAX;
        }
        // Frame-rate independent easing: the same movement at 60fps and 144.
        const ease = 1 - Math.exp(-dt * 2.2);
        camLo += (wantLo - camLo) * ease;
        camHi += (wantHi - camHi) * ease;
      };

      /** How much closer the view is than the whole field. */
      const camZoom = (): number => FIELD_SPAN / Math.max(1, camHi - camLo);

      /**
       * Field position → screen Y. Low field values sit at the BOTTOM, which is
       * where side A spawns, so the player's own army is nearest to them.
       */
      const toScreenY = (pos: number, h: number): number => {
        const pad = h * 0.07;
        const usable = h - pad * 2;
        return h - pad - ((pos - camLo) / Math.max(1, camHi - camLo)) * usable;
      };
      /**
       * Lane → screen X. The two sides share a lane, so each is nudged off its
       * centreline: head-on they used to stack exactly on top of each other and
       * the rear one vanished.
       */
      /** How far a squad spreads either side of its lane centre. */
      /**
       * The silhouettes are drawn at a size that suited a wide field seen from
       * the side. On a phone-width portrait floor they came out about 20px tall
       * and read as specks, so they are scaled to the width they have to share.
       *
       * The divisor holds a man at roughly 7.3% of the board's width, which is
       * what the reference game draws — measured off its recording as an 80px
       * body against an 1100px board. The previous formula held a fixed pixel
       * size instead, so a man was 7% of a wide board and 12% of a narrow one:
       * the same figure read as an army on a tablet and as a crowd of giants on
       * a phone. A test pins the proportion at both ends now.
       *
       * At this size identity comes from silhouette, base-ring colour and
       * formation shape, NOT from detail. The detail lives on the card.
       */
      // `unitScale` is imported: see motion.ts for why the proportion moved.

      const paintFloor = (w: number, h: number): void => {
        ground.clear();

        // Surround: the city or crowd the arena sits in.
        ground.rect(0, 0, w, h).fill(floorDeep);

        const inset = Math.min(w * 0.06, 22);
        const fx = inset;
        const fy = h * 0.045;
        const fw = w - inset * 2;
        const fh = h - fy * 2;
        const r = Math.min(28, fw * 0.09);

        /**
         * The carpet border.
         *
         * The floor is a BOARD, not terrain — nobody fought a battle on a rug,
         * and the game must not imply they did. But a carpet is identified by
         * its borders rather than its field (it is how you tell a Tabriz from a
         * Kashan across a room), so the pattern goes in the surround, which was
         * flat colour doing nothing, and the fighting floor stays quiet.
         *
         * That ordering is also what keeps units readable. They draw at
         * 22-85px, and this codebase has already lost one legibility fight at
         * that scale — six infantry at 26px were the same brown smudge. No
         * sprite ever stands in the surround, so the border can carry real
         * contrast while the field carries almost none.
         *
         * The motif is a stepped lozenge run, reduced from the star-and-cross
         * rosettes of the PAZYRYK carpet — 5th-4th c. BCE, frozen in a Saka
         * kurgan in the Altai, the oldest knotted pile carpet that survives and
         * the only one contemporary with these thirteen arenas. Its borders are
         * griffins, fallow deer and horsemen; none of those read at this size,
         * the geometry does.
         *
         * It is deliberately ONE design for all thirteen. Every current arena
         * is Achaemenid, so under the two-axis rule in DESIGN-CARPET.md they
         * all share a floor — the named city schools (Tabriz, Isfahan, Mashhad)
         * do not exist yet and arrive only with the Safavid and Afsharid
         * arenas. Per-arena identity comes from `themeFor`, which recolours
         * this same geometry thirteen ways for free.
         */
        // Clamped to what the surround can actually hold. `inset` is
        // min(w * 0.06, 22), so on a narrow phone an unclamped band runs off
        // the left edge and the border reads as broken rather than as a border.
        const band = Math.max(5, Math.min(inset - 6, inset * 0.62));
        const step = band * 1.45;
        const lozenge = (px: number, py: number, k: number): void => {
          ground
            .moveTo(px, py - k)
            .lineTo(px + k, py)
            .lineTo(px, py + k)
            .lineTo(px - k, py)
            .lineTo(px, py - k);
        };
        const k = band * 0.30;
        for (let px = fx - 5 + step / 2; px < fx + fw + 5; px += step) {
          lozenge(px, fy - 5 - band / 2, k);
          lozenge(px, fy + fh + 5 + band / 2, k);
        }
        for (let py = fy - 5 + step / 2; py < fy + fh + 5; py += step) {
          lozenge(fx - 5 - band / 2, py, k);
          lozenge(fx + fw + 5 + band / 2, py, k);
        }
        ground.stroke({ width: 1.4, color: accent, alpha: 0.5 });

        // Guard stripes, which is how a real border is bounded on both sides.
        ground
          .roundRect(fx - 5 - band, fy - 5 - band, fw + 10 + band * 2, fh + 10 + band * 2, r + 4 + band)
          .stroke({ width: 1, color: accent, alpha: 0.35 });

        // The fighting floor.
        ground.roundRect(fx - 5, fy - 5, fw + 10, fh + 10, r + 4).fill(accent);
        ground.roundRect(fx, fy, fw, fh, r).fill(floor);

        // Territory. Each half carries a wash of its own side's colour, so
        // "my end" and "their end" read instantly instead of having to be
        // worked out from where the sprites happen to be standing. Kept very
        // low so it tints the ground rather than repainting it — the arena's
        // own floor colour still has to come through.
        //
        // Side A holds the BOTTOM of the screen and B the top, which is the
        // same convention `toScreenY` and the advance direction use.
        // Raised from 0.11. With the floor graded down, the two washes are the
        // main source of hue on the board — they were 0.9% of the pixels.
        const halfAlpha = 0.2;
        ground
          .roundRect(fx, fy, fw, fh / 2, r)
          .fill({ color: SIDE_COLOR.b, alpha: halfAlpha });
        ground
          .roundRect(fx, fy + fh / 2, fw, fh / 2, r)
          .fill({ color: SIDE_COLOR.a, alpha: halfAlpha });

        // Tile grid, denser along the axis of advance so distance reads.
        const cols = 6;
        const rows = 14;
        for (let c = 1; c < cols; c++) {
          const x = fx + (fw / cols) * c;
          ground.moveTo(x, fy).lineTo(x, fy + fh);
        }
        for (let rIdx = 1; rIdx < rows; rIdx++) {
          const y = fy + (fh / rows) * rIdx;
          ground.moveTo(fx, y).lineTo(fx + fw, y);
        }
        ground.stroke({ width: 1, color: rim, alpha: 0.35 });

        // Halfway line — where the two ranks meet.
        ground
          .moveTo(fx, fy + fh / 2)
          .lineTo(fx + fw, fy + fh / 2)
          .stroke({ width: 2, color: accent, alpha: 0.55 });

        // Centre medallion.
        const cx = fx + fw / 2;
        const cy = fy + fh / 2;
        const rad = Math.min(fw, fh) * 0.17;
        ground.circle(cx, cy, rad).stroke({ width: 3, color: accent, alpha: 0.45 });
        ground.circle(cx, cy, rad * 0.55).stroke({ width: 2, color: accent, alpha: 0.3 });
        for (let i = 0; i < 8; i++) {
          const a = (i / 8) * Math.PI * 2;
          ground
            .moveTo(cx + Math.cos(a) * rad * 0.55, cy + Math.sin(a) * rad * 0.55)
            .lineTo(cx + Math.cos(a) * rad, cy + Math.sin(a) * rad);
        }
        ground.stroke({ width: 1.5, color: accent, alpha: 0.3 });

        // Close the eight spokes into a star. The centre was already called a
        // medallion in this file before any of the carpet work — the board had
        // the shape of one and only wanted the geometry.
        for (let i = 0; i < 8; i++) {
          const a1 = (i / 8) * Math.PI * 2;
          const a2 = ((i + 0.5) / 8) * Math.PI * 2;
          const a3 = ((i + 1) / 8) * Math.PI * 2;
          ground
            .moveTo(cx + Math.cos(a1) * rad, cy + Math.sin(a1) * rad)
            .lineTo(cx + Math.cos(a2) * rad * 0.62, cy + Math.sin(a2) * rad * 0.62)
            .lineTo(cx + Math.cos(a3) * rad, cy + Math.sin(a3) * rad);
        }
        ground.stroke({ width: 1.2, color: accent, alpha: 0.22 });

        // The two baselines, so it is obvious which end is yours.
        ground.roundRect(fx + fw * 0.2, fy + fh - 8, fw * 0.6, 5, 3).fill(SIDE_COLOR.a);
        ground.roundRect(fx + fw * 0.2, fy + 3, fw * 0.6, 5, 3).fill(SIDE_COLOR.b);

        // Corner posts.
        for (const [px, py] of [
          [fx, fy],
          [fx + fw, fy],
          [fx, fy + fh],
          [fx + fw, fy + fh],
        ]) {
          ground.circle(px, py, 9).fill(accent);
          ground.circle(px, py, 9).stroke({ width: 2, color: rim });
        }
      };

      // Dev only: a harness can ask for each new battle to wait at tick 0, so
      // it is measured from its first frame rather than from whenever the
      // harness next got to run.
      if (import.meta.env.DEV && (window as unknown as { __holdBattle?: boolean }).__holdBattle) {
        instance.ticker.stop();
      }
      instance.ticker.add((ticker) => {
        const w = instance.screen.width;
        const h = instance.screen.height;
        paintFloor(w, h);

        const dt = ticker.deltaMS / 1000;
        realClock += dt;
        /*
         * Hit-stop: on a heavy impact the whole battle runs at a crawl for a
         * few hundredths of a second. It is felt rather than seen, and it is
         * the single cheapest thing that makes a blow land. Applied to the
         * playback clock itself, so the log, the gestures and the arrows all
         * freeze together.
         */
        const hs = stepHitStop(hitStop, dt);
        hitStop = hs.next;
        const dtScaled = dt * hs.scale;
        trauma = decayTrauma(trauma, dt, TRAUMA_DECAY);
        const shake = shakeOffset(trauma, SHAKE_PX, realClock);
        world.position.set(shake.x, shake.y);
        /*
         * ONE clock, and it is the log's — see `playbackSeconds` in motion.ts.
         * `dtPlay` is how much playback time this frame covered, `elapsedTicks`
         * is derived from it, and `clock` is derived from those, so none of the
         * three can drift apart from the others.
         *
         * The tick count used to be its own expression alongside `dtPlay`, which
         * is how the battle PACE would have slowed the men while leaving every
         * gesture at its old duration.
         */
        const dtPlay = playbackSeconds(dtScaled, speedRef.current);
        elapsedTicks += dtPlay * TICK_RATE;
        const clock = playbackClock(elapsedTicks, TICK_RATE);

        const idx = Math.min(Math.floor(elapsedTicks), log.frames.length - 1);
        const frame = log.frames[idx];
        /*
         * The round is decided. The board stays up behind the result banner, so
         * the ending plays in time the player was already spending.
         *
         * A ONE-FRAME log is not a finished battle — it is `standingLog`, the
         * still preview the board shows while the player is choosing a card. Its
         * winner is 'draw', so without this the whole army stood on the draft
         * screen slowly dropping its head as though it had just lost. Caught by
         * photographing the celebration and finding it on the wrong screen.
         */
        const over = log.frames.length > 1 && idx >= log.frames.length - 1;
        if (over) cheerT += dtPlay;
        /** How high the highest celebrating man is off the ground, for the harness. */
        let cheerLift = 0;
        // Squad totals for the health bars, recomputed each frame — cheap, and
        // it means the bar cannot drift out of step with the men under it.
        const squadHp = new Map<string, { hp: number; max: number }>();
        /*
         * Which man carries his squad's health bar: the LOWEST-FILE SURVIVOR,
         * recomputed every frame.
         *
         * It used to be whoever happened to be file 0, and the dead skip the
         * drawing path entirely — so the moment that one man fell, a squad that
         * was still fighting lost its health bar for the rest of the battle.
         */
        const barCarrier = new Map<string, { uid: number; file: number }>();
        for (const p2 of frame.pos) {
          const m = byUid.get(p2.uid);
          if (!m) continue;
          const cur = squadHp.get(m.squad) ?? { hp: 0, max: 0 };
          cur.hp += Math.max(0, p2.hp);
          cur.max += m.maxHp;
          squadHp.set(m.squad, cur);
          if (p2.hp > 0) {
            const held = barCarrier.get(m.squad);
            if (!held || m.file < held.file) barCarrier.set(m.squad, { uid: p2.uid, file: m.file });
          }
        }
        const nextFrame = log.frames[Math.min(idx + 1, log.frames.length - 1)];
        const alpha = Math.min(1, elapsedTicks - idx);

        // How many log frames this redraw crossed. Large when the player skips,
        // and effects are suppressed then — see `fresh` below.
        const crossed = idx - lastAppliedFrame;
        // Apply every event we skipped past, so a 4x replay never drops a death.
        for (let f = lastAppliedFrame + 1; f <= idx; f++) {
          for (const ev of log.frames[f].events) {
            // Effects only for frames we are actually watching. Skipping to the
            // end crosses hundreds of events at once, and a shake and a sky full
            // of sparks for a fight nobody saw is noise, not feedback.
            const fresh = idx - f <= 3;
            if (ev.t === 'order') {
              bursts.push({ uid: ev.uid, life: ORDER_LIFE });
              if (fresh) {
                trauma = addTrauma(trauma, 0.8);
                if (speedRef.current <= 2) hitStop = requestHitStop(hitStop);
              }
              continue;
            }
            if (ev.t !== 'attack') continue;
            // Impact only. The swing and the arrow were started earlier, by the
            // plan below, so that both LAND here rather than beginning here.
            flashes.push({ from: ev.uid, to: ev.target, mult: ev.mult, life: FLASH_LIFE });
            const victim = sprites.get(ev.target);
            const attacker = sprites.get(ev.uid);
            if (victim) victim.hurt = HURT_LIFE;
            /*
             * The FIRST blow of an engagement is the charge arriving; every blow
             * after it is the fight going on. Only the first one shakes the
             * camera. Measured the other way round, a cavalry melee held trauma
             * at 0.7–0.9 for most of a round — the screen never stopped moving —
             * because every swing of a horseman counted as a charge.
             */
            const opening = !attacker || f - attacker.lastImpactTick > ENGAGE_TICKS;
            // Both men are now in a fight with each other. The attacker always
            // turns on his target; the victim turns on his attacker only if he
            // was not already busy with someone else.
            if (attacker) {
              attacker.target = ev.target;
              attacker.lastHitTick = f;
              attacker.lastImpactTick = f;
            }
            if (victim) {
              if (victim.target < 0 || f - victim.lastHitTick > ENGAGE_TICKS) victim.target = ev.uid;
              victim.lastHitTick = f;
            }
            if (fresh && victim && Number.isFinite(victim.sx)) {
              const style = attacker ? motionFor(attacker.silhouette).attack : 'thrust';
              const heavy = style === 'charge' || style === 'stomp';
              const ranged = style === 'shoot';
              const color = ev.mult > 1 ? PALETTE.gold : ev.mult < 1 ? PALETTE.ochreHi : PALETTE.white;
              const seed = ev.uid * 31 + f;
              const at = victim.sy - SPRITE_HEIGHT * 0.45;
              sparks(victim.sx, at, ranged ? 2 : heavy ? 7 : 4, color, seed);
              if (heavy) {
                // A horse or an elephant striking kicks up sand every time.
                puff(victim.sx, victim.sy, opening ? 5 : 2, opening ? 48 : 24, seed);
                if (opening && chargeShookAt !== f) {
                  // The charge ARRIVING: the camera takes it, time catches. Once
                  // per log frame — four horsemen of one squad arriving on the
                  // same tick is one impact, not four; stacked, they pinned
                  // trauma at 1.0.
                  chargeShookAt = f;
                  trauma = addTrauma(trauma, 0.6);
                  if (speedRef.current <= 2) hitStop = requestHitStop(hitStop);
                }
              }
            }
          }
        }
        lastAppliedFrame = idx;

        const screen = new Map<number, { x: number; y: number }>();

        /*
         * STEERING — where each man wants to stand this frame.
         *
         * Pass one works out a target for every man: his formation column while
         * he marches, and once he is fighting, a spot pulled toward his opponent
         * and — for melee — closed along the field to contact. Pass two pushes
         * apart the men that end up on top of each other. Pass three, the draw
         * loop below, eases each man toward his spot. None of it touches the
         * log: it moves where a man is DRAWN, not where the simulation says he is.
         */
        /*
         * Aim the view at the living, then work out how big a man is under it.
         * Every size below — body width, contact distance, the sprite scale,
         * the shadows, the gestures — comes off `uk`, so folding the camera in
         * here is what makes the whole board zoom coherently instead of the
         * men floating at one scale over a field drawn at another.
         */
        {
          let lo = Infinity;
          let hi = -Infinity;
          for (const q of frame.pos) {
            if (q.hp <= 0) continue;
            if (q.x < lo) lo = q.x;
            if (q.x > hi) hi = q.x;
          }
          if (lo <= hi) aimCamera(lo, hi, dt);
        }
        // Board width and camera together — see `figureScale` for why it is a
        // square root rather than the zoom itself.
        const uk = figureScale(w, camZoom());
        const bodyW = SPRITE_HEIGHT * uk * 0.62;
        /*
         * How close two enemies stand once they are fighting.
         *
         * Was 0.42 of a body height, which is INSIDE the other man: the two
         * ranks overlapped, the sprites merged into one mass, and a fight read
         * as a pile rather than as a line — "they just bump into each other".
         * At 0.62 there is a weapon's length between them, so the lunge has
         * somewhere to travel and the gap closes and opens as blows land.
         */
        const contact = SPRITE_HEIGHT * uk * 0.62;
        // Quantised: a plan rebuilt every frame would jitter the line as the
        // camera eased, and a plan never rebuilt would keep phone spacing on a
        // zoomed board.
        const planKey = w + Math.round(uk * 20) / 20;
        if (!linePlan || planWidth !== planKey) {
          const usable = w - w * 0.22;
          linePlan = {
            a: lineOfSquads(sideSquads.a, bodyW, usable),
            b: lineOfSquads(sideSquads.b, bodyW, usable),
          };
          planWidth = planKey;
        }
        const wantX = new Float64Array(frame.pos.length);
        const wantY = new Float64Array(frame.pos.length);
        const living: number[] = [];
        /*
         * Where every living man was last frame, per side, for finding the
         * nearest enemy ON SCREEN.
         *
         * Steering toward the LOGGED target was the first version and it dragged
         * every melee to the left edge of the board: the simulation breaks
         * targeting ties by lowest uid, so a whole squad aims at the same enemy —
         * the one in the leftmost column — and a whole squad steering at one man
         * is a squad walking left. The log still decides who takes the blow; the
         * nearest man on screen decides where a body stands.
         */
        const foes: Record<'a' | 'b', { x: number; y: number; uid: number }[]> = { a: [], b: [] };
        for (const q of frame.pos) {
          const sp = sprites.get(q.uid);
          const m = byUid.get(q.uid);
          if (sp && m && q.hp > 0 && Number.isFinite(sp.sx)) foes[m.side].push({ x: sp.sx, y: sp.sy, uid: q.uid });
        }
        for (let i = 0; i < frame.pos.length; i++) {
          const p = frame.pos[i];
          const np = nextFrame.pos[i];
          const meta = log.roster[i];
          const sprite = sprites.get(p.uid);
          if (!sprite || !meta) continue;
          const baseY = toScreenY(p.x + (np.x - p.x) * alpha, h);
          /*
           * A BLOCK, not a line. The simulation gives a squad one advance
           * coordinate, so every man of it stood at the same distance up the
           * field — a squad of ten was a wire ten wide and one deep, and two
           * armies of wires is a diagram of a battle rather than a battle.
           *
           * `squadSlot` puts him in a rank, and the rank offset is applied
           * BACKWARDS from the sim's position, so the front rank stands exactly
           * where the log says the squad is and the rest stack up behind it.
           * Nothing moves forward of the simulation's line.
           */
          const n = squadSize.get(meta.squad) ?? 1;
          // Each squad builds its block inside its own allowance on the line.
          const place = linePlan[meta.side].get(meta.squad);
          const slot = squadSlot(ordinal.get(p.uid) ?? 0, n, bodyW, place?.width ?? w - w * 0.22);
          const homeX = w / 2 + (place?.centre ?? 0) + slot.dx;
          // Side A advances up the screen, so "back" for A is down it.
          const homeY = baseY + slot.dy * (meta.side === 'a' ? 1 : -1);
          sprite.baseY = homeY;
          sprite.rank = slot.row;
          let wx = homeX;
          let wy = homeY;
          const ranged = Boolean(motionFor(sprite.silhouette).projectile);
          // The nearest living enemy on screen, measured from where he stands.
          let near: { x: number; y: number; uid: number } | null = null;
          if (Number.isFinite(sprite.sx)) {
            let best = Infinity;
            for (const e of foes[meta.side === 'a' ? 'b' : 'a']) {
              const d = (e.x - sprite.sx) ** 2 + ((e.y - sprite.sy) * 1.4) ** 2;
              if (d < best) {
                best = d;
                near = e;
              }
            }
            // Engaged if the log says he is fighting, or an enemy is simply
            // close enough to reach — men react to a line arriving, not only
            // to the first blow.
            const reach = bodyW * 3.2;
            const logged = sprite.target >= 0 && idx - sprite.lastHitTick <= ENGAGE_TICKS;
            if (!(near && (logged || best < reach * reach))) near = null;
          }
          if (near) {
            const foeSprite = sprites.get(near.uid);
            // An archer only turns a little toward what he is shooting. A man
            // with a spear steps across to face his — and only if his man is
            // near enough to step to.
            const sideways = Math.abs(near.x - homeX);
            const chase = ranged || sideways <= bodyW * SIDESTEP_REACH;
            if (chase) {
              wx = engagedX(homeX, near.x, ranged ? 0.15 : 0.7, bodyW * (ranged ? 0.6 : SIDESTEP));
            }
            if (!ranged && foeSprite && Number.isFinite(foeSprite.baseY)) {
              /*
               * Half each: both men close, so between them they meet at contact
               * rather than walking through each other. Only the FRONT rank
               * closes freely — a rear rank that walked to contact would march
               * straight through the men in front of it and the block would
               * collapse back into the single line this replaced.
               */
              const reachOfRank = slot.row === 0 ? 1 : 0.3;
              wy = homeY + closeGap(homeY, foeSprite.baseY, contact, MAX_CLOSE * uk * 2 * reachOfRank) * 0.5;
              /*
               * A melee is not two straight rows pressed together. Each man
               * takes his own depth and his own sideways offset once he is in
               * it — some pushed forward, some held back, pairs drifting apart —
               * so the contact line breaks into a scrum. From a hash of his uid,
               * so the same fight breaks up the same way every replay.
               */
              // Enough scatter to break the two rows up, not enough to close
              // the gap they are fighting across: at 1.3 the jitter was wider
              // than the stand-off itself, so half the men ended up back inside
              // their opponents and the line looked like a scrum again.
              wy += (hash01(p.uid, 91) - 0.5) * contact * 0.7;
              wx += (hash01(p.uid, 57) - 0.5) * bodyW * 0.9;
            }
          }
          sprite.homeX = homeX;
          // Who he should be turned toward: the man he is fighting if he has
          // one, otherwise nobody and he keeps the way he is already facing.
          sprite.faceAt = near ? near.x : Number.NaN;
          wantX[i] = wx;
          wantY[i] = wy;
          if (p.hp > 0) living.push(i);
        }
        {
          const bodies = living.map((i) => {
            const sp = sprites.get(frame.pos[i].uid)!;
            return {
              x: Number.isFinite(sp.sx) ? sp.sx : wantX[i],
              y: Number.isFinite(sp.sy) ? sp.sy : wantY[i],
              r: bodyW * 0.5,
            };
          });
          const push = separate(bodies, 0.9, bodyW * 0.72);
          living.forEach((i, j) => {
            wantX[i] += push.dx[j];
            wantY[i] += push.dy[j];
          });
        }
        /*
         * THE LINE HOLDS — nobody walks through the enemy rank.
         *
         * Everything above is a soft force: a man is pulled toward his opponent,
         * pushed off his neighbours, and scattered a little so the contact line
         * is not two straight rows. Soft forces compose, and what they composed
         * into was the two armies standing INSIDE each other — teal rings and
         * red rings in one mixed heap, which is what "they just bump into each
         * other" describes.
         *
         * So the last word is a hard constraint. Side A fights from below and
         * side B from above; a man may reach the line and no further. It is
         * applied after the scatter and the separation, because a constraint
         * that anything is allowed to override is not a constraint.
         */
        {
          const minGap = contact * 0.9;
          for (const i of living) {
            const meta = log.roster[i];
            if (!meta) continue;
            // Side A spawns at the bottom of the board, which is LARGER y.
            const below = meta.side === 'a';
            let nearestY = Number.NaN;
            let best = Infinity;
            for (const e of foes[below ? 'b' : 'a']) {
              const dx = Math.abs(e.x - wantX[i]);
              if (dx < best) {
                best = dx;
                nearestY = e.y;
              }
            }
            // Only against a man he could actually run into: an enemy two
            // squads away across the line must not drag him backwards.
            if (!Number.isFinite(nearestY) || best > bodyW * 2.2) continue;
            wantY[i] = below
              ? Math.max(wantY[i], nearestY + minGap)
              : Math.min(wantY[i], nearestY - minGap);
          }
        }
        shadowLayer.clear();
        const squadSpot = new Map<string, { x: number; n: number; top: number; hpFrac: number }>();

        for (let i = 0; i < frame.pos.length; i++) {
          const p = frame.pos[i];
          const np = nextFrame.pos[i];
          const meta = log.roster[i];
          const sprite = sprites.get(p.uid);
          if (!sprite || !meta) continue;

          const profile = motionFor(sprite.silhouette);
          const alive = p.hp > 0;
          if (!Number.isFinite(sprite.sx)) {
            sprite.sx = wantX[i];
            sprite.sy = wantY[i];
          }
          const prevSy = sprite.sy;
          // The dead do not steer. A man stays where he fell.
          if (alive) {
            sprite.sx = approach(sprite.sx, wantX[i], STEER_X_RATE, dtPlay);
            sprite.sy = approach(sprite.sy, wantY[i], STEER_Y_RATE, dtPlay);
          }
          const moving = Math.abs(np.x - p.x) > 0.01;
          const g = gait(profile, clock, sprite.phase, moving);

          // Side A advances up the screen, side B down it.
          // Which way he ADVANCES along the field. Not the same thing as which
          // way he is turned, which is `sprite.face` and points at his opponent.
          const advance = meta.side === 'a' ? -1 : 1;

          /*
           * Which hand he swings with. Fixed per man from his uid, so a rank
           * does not swing in unison like a chorus line — half the line cuts
           * left and half cuts right, which is most of what makes a melee look
           * like a melee instead of a machine.
           */
          const hand = sprite.uid % 2 === 0 ? 1 : -1;

          let lunge = 0;
          let spin = 0;
          let swipe = 0;
          if (sprite.swing > 0) {
            sprite.swing = Math.max(0, sprite.swing - dtPlay);
            const k = 1 - sprite.swing / SWING_LIFE;
            const pose = attackPose(profile.attack, k);
            // Scaled with the figure. The pose is in sprite-local pixels, and
            // applying it raw meant a blow that read at phone size shrank to
            // nothing relative to a bigger man on a wider board.
            lunge = pose.lunge * advance * uk;
            spin = pose.spin * advance + pose.spin * hand * 0.5;
            // A swing travels ACROSS the body, not just forward. Cuts and
            // lashes arc sideways; a thrust and a shot do not.
            const lateral = (profile.attack === 'swing' || profile.attack === 'lash' ? 7 : 0) * uk;
            swipe = Math.sin(k * Math.PI) * lateral * hand;
          }

          // Recoil: a short jolt away from whoever hit them, and a squash, so a
          // landed blow is visible on the body and not only in the flare.
          let recoil = 0;
          let stagger = 0;
          let squash = 1;
          if (sprite.hurt > 0) {
            sprite.hurt = Math.max(0, sprite.hurt - dtPlay);
            const h = sprite.hurt / HURT_LIFE;
            // Thrown back hard, then walking back onto his line. The lateral
            // stagger is what stops a struck rank looking like it bounced.
            const ease = h * h;
            recoil = ease * KNOCKBACK * -advance;
            stagger = ease * STAGGER * hand;
            squash = 1 + h * 0.2;
          }

          /*
           * Turn toward the fight. Every sprite is painted facing right, and
           * nothing ever turned one round, so a man fighting someone on his
           * left fought over his own shoulder. The deadzone is a quarter of a
           * body: an opponent nearly dead ahead leaves him as he is, instead of
           * flipping him every frame and making the whole line shimmer.
           */
          if (alive && Number.isFinite(sprite.faceAt)) {
            sprite.face = facing(sprite.face, sprite.faceAt - sprite.sx, bodyW * 0.25);
          }
          const x = sprite.sx + g.sway + stagger + swipe;
          /*
           * Depth is the simulation's, not the renderer's. Squads spawn three
           * field units apart and that already reads as rows once the men are
           * spread sideways, so the old render-side rank offset is gone with
           * the lanes that made it necessary.
           */
          const y = sprite.sy - Math.abs(g.bob) + lunge + recoil;
          screen.set(p.uid, { x, y });
          // The same `uk` the steering used, camera included.
          const k = uk;
          sprite.root.position.set(x, y);
          sprite.root.scale.set(k * squash * sprite.face, k / squash);
          sprite.root.zIndex = y;
          // The ring is ON THE GROUND. Counter the bob so a galloping horse lifts
          // off its ring instead of carrying it into the air.
          sprite.ring.position.y = Math.abs(g.bob) / (k / squash);
          if (alive) {
            // A shadow that stays on the floor while the body bobs is most of
            // what makes a figure stand on something rather than float over it.
            shadowLayer
              .ellipse(sprite.sx, sprite.sy + 1.5, sprite.ringRx * k * 1.25, sprite.ringRx * k * 0.46)
              .fill({ color: 0x000000, alpha: 0.24 });
            // Dust off the feet of anything heavy that is really moving.
            const speedPx = dtPlay > 0 ? Math.abs(sprite.sy - prevSy) / dtPlay : 0;
            const heavy = profile.airborne || profile.attack === 'charge' || profile.attack === 'stomp';
            if (heavy && speedPx > 35) {
              sprite.dustT -= dtPlay;
              if (sprite.dustT <= 0) {
                sprite.dustT = 0.06;
                puff(sprite.sx + (hash01(sprite.uid, idx) - 0.5) * 10, sprite.sy + 1, 1, 18, sprite.uid * 7 + idx);
              }
            }
          }
          // The health bar is chrome, not anatomy: counter-scale it so it stays
          // the same size on an elephant and on an archer. The recoil squash is
          // non-uniform, so this has to undo BOTH axes — a plain 1/k would leave
          // the bar squashing along with the body every time the unit was hit.
          sprite.bar.scale.set(1 / (k * squash), squash / k);
          /*
           * Wind. A rank of men holding spears is never still, and a field that
           * only moves when someone swings reads as a diagram rather than an
           * army. Each man carries his own phase, so the line RIPPLES across
           * instead of tilting as one slab — which is the whole difference
           * between wind and a wobble.
           *
           * Driven off elapsedTicks rather than a clock, so it stays inside the
           * determinism rule: nothing in this file may make two machines
           * disagree about a frame.
           */
          /*
           * Pose the rig from the SAME stride clock the procedural gait runs
           * on, so a rigged horse and an unrigged one stay in step with each
           * other and with the bob. The rig replaces the leg motion; the bob,
           * sway and lean stay, because a real gallop has all of it.
           */
          if (sprite.rig) {
            const stride = clock * profile.bobHz + sprite.phase;
            const clip = sprite.mounted ? gallop : march;
            applyPose(sprite.rig, moving ? clip(stride % 1) : idle(stride % 1));
          }

          /*
           * The ending. Winners jump and punch the air, losers drop their heads.
           * Applied on top of everything else so a man who is mid-swing when the
           * round ends finishes his swing and then celebrates.
           */
          let endLift = 0;
          let endTilt = 0;
          if (over) {
            const end = cheer(cheerT, sprite.phase, log.winner === meta.side);
            endLift = end.lift;
            cheerLift = Math.max(cheerLift, -end.lift);
            endTilt = end.tilt * (meta.side === 'a' ? 1 : -1);
            sprite.root.position.set(x, y + endLift);
          }

          // Idle sway on top of the gait, phased per man so a rank ripples
          // across rather than tilting as one body.
          const wind = elapsedTicks * WIND_SPEED + sprite.phase * Math.PI * 2;
          sprite.body.rotation = g.tilt + spin + Math.sin(wind) * WIND_TILT + endTilt;

          const hpFrac = meta.maxHp > 0 ? p.hp / meta.maxHp : 0;
          if (p.hp <= 0) {
            /*
             * He falls over. The old death was a fade with a slow spin, which
             * at this size read as a sprite being switched off rather than a
             * man going down — and with ninety men on the board, deaths are
             * most of what the eye is actually watching.
             *
             * Topple to flat, drop onto the ground line, and only then fade.
             */
            if (sprite.fall === 0 && !sprite.corpse && crossed <= 3) {
              // He hits the ground: a puff of sand, and a horse going down is felt.
              puff(sprite.sx, sprite.sy, sprite.mounted && sprite.rig ? 6 : 3, 30, sprite.uid * 13 + idx);
              if (profile.airborne) trauma = addTrauma(trauma, 0.25);
            }
            sprite.fall = Math.min(FALL_LIFE, sprite.fall + dtPlay);
            const f = sprite.fall / FALL_LIFE;
            const ease = 1 - (1 - f) * (1 - f);
            sprite.body.rotation = ease * (Math.PI / 2) * hand;
            sprite.root.position.set(sprite.sx + ease * 3 * hand, sprite.sy + ease * 5);
            /*
             * The dead STAY. The old death faded to nothing in half a second, so
             * a field ninety men had fought over was empty carpet by the end —
             * no aftermath, no sense that anything had happened. Now a fallen man
             * dims to half and keeps his place, on a layer below the living.
             */
            sprite.root.alpha = f < 0.6 ? 1 : 1 - ((f - 0.6) / 0.4) * 0.5;
            sprite.bar.clear();
            if (f >= 1 && !sprite.corpse) {
              sprite.corpse = true;
              sprite.ring.visible = false;
              sprite.root.tint = CORPSE_TINT;
              corpseLayer.addChild(sprite.root);
            }
            continue;
          } else {
            if (sprite.corpse || sprite.fall > 0) {
              // Stood back up — Cyrus's order revives a whole squad.
              sprite.corpse = false;
              sprite.fall = 0;
              sprite.ring.visible = true;
              sprite.root.tint = 0xffffff;
              unitLayer.addChild(sprite.root);
            }
            sprite.root.alpha = 1;
            sprite.bar.clear();
            // The bar is counter-scaled, so this offset is in WORLD pixels — it
            // has to include the unit's scale or it lands on the chest instead
            // of above the head, which is exactly what it did first time.
            /*
             * ONE bar per squad, carried by the front man, showing the SQUAD's
             * health rather than his own. Eighty individual bars was unreadable
             * noise, and a man's own sliver of health is not a number anyone is
             * making decisions with — the squad's is.
             */
            // Gather the squad's middle and its topmost head for the bar layer.
            {
              const top = sprite.tall ? y - SPRITE_HEIGHT * 0.94 * k - 8 : y - 22 * k - 10;
              const acc = squadSpot.get(meta.squad);
              if (acc) {
                acc.x += sprite.sx;
                acc.n += 1;
                acc.top = Math.min(acc.top, top);
              } else {
                squadSpot.set(meta.squad, { x: sprite.sx, n: 1, top, hpFrac });
              }
            }
          }
        }

        barLayer.clear();
        {
          // Two squads fighting on the same spot would draw their bars on top of
          // each other. Placed top-down, each bar steps up clear of any bar
          // already placed beneath it.
          const placed: { x: number; y: number }[] = [];
          const spots = [...squadSpot.entries()].sort((p1, p2) => p2[1].top - p1[1].top);
          for (const [squad, spot] of spots) {
            const sq = squadHp.get(squad);
            const frac = sq && sq.max > 0 ? sq.hp / sq.max : spot.hpFrac;
            const bx = spot.x / spot.n;
            let by = spot.top;
            for (let guard = 0; guard < 8; guard++) {
              const hitBar = placed.find((q) => Math.abs(q.x - bx) < 32 && Math.abs(q.y - by) < 9);
              if (!hitBar) break;
              by = hitBar.y - 9;
            }
            placed.push({ x: bx, y: by });
            barLayer.roundRect(bx - 15, by, 30, 7, 3).fill(PALETTE.ink);
            barLayer
              .roundRect(bx - 13, by + 2, 26 * Math.max(0, frac), 3, 2)
              .fill(frac > 0.5 ? PALETTE.turquoise : frac > 0.25 ? PALETTE.gold : PALETTE.ochreHi);
          }
        }

        // Anything scheduled to START in the frames we just crossed.
        for (let f = lastPlanFrame + 1; f <= idx; f++) {
          for (const plan of planned.get(f) ?? []) {
            if (plan.swing) {
              const shooter = sprites.get(plan.from);
              if (shooter) {
                shooter.swing = SWING_LIFE;
                // He turns on his man as he winds up, not after the blow lands.
                shooter.target = plan.to;
                shooter.lastHitTick = f;
              }
              continue;
            }
            const from = screen.get(plan.from);
            const to = screen.get(plan.to);
            if (!from || !to || !plan.projectile) continue;
            shots.push({
              toUid: plan.to,
              startTick: plan.atTick,
              endTick: plan.eventTick,
              fromX: from.x, fromY: from.y, toX: to.x, toY: to.y,
              kind: plan.projectile.kind,
            });
          }
        }
        lastPlanFrame = idx;

        // --- projectiles ------------------------------------------------------
        //
        // Flight runs on PLAYBACK TICKS, so an arrow launched at 1x and watched
        // at 4x still lands on its logged tick. Driving it off `dt` meant the
        // combat outran its own arrows the moment the speed control was used.
        shotLayer.clear();
        for (let i = shots.length - 1; i >= 0; i--) {
          const s = shots[i];
          const span = Math.max(1, s.endTick - s.startTick);
          const k = (elapsedTicks - s.startTick) / span;
          if (k >= 1) {
            shots.splice(i, 1);
            continue;
          }
          // Track the target: over a long shot the victim has moved, and an
          // arrow that lands where he used to be reads as a miss.
          const live = screen.get(s.toUid);
          if (live) {
            s.toX = live.x;
            s.toY = live.y;
          }
          /*
           * Up and over, not a straight line. A volley is shot high and drops,
           * and on a board seen from above the only way to show height is the
           * gap between the arrow and its shadow on the carpet.
           */
          const dist = Math.hypot(s.toX - s.fromX, s.toY - s.fromY);
          const pt = arcPoint(s.fromX, s.fromY - 14, s.toX, s.toY - 14, k, arcHeight(dist));
          const ang = pt.angle;
          shotLayer.ellipse(pt.x, pt.groundY + 14, 2.4, 1).fill({ color: 0x000000, alpha: 0.28 });
          if (s.kind === 'arrow') {
            const len = 10;
            shotLayer
              .moveTo(pt.x - Math.cos(ang) * len, pt.y - Math.sin(ang) * len)
              .lineTo(pt.x, pt.y)
              .stroke({ width: 2, color: PALETTE.gold });
            shotLayer.circle(pt.x, pt.y, 1.6).fill(PALETTE.white);
          } else {
            shotLayer.circle(pt.x, pt.y, 2.6).fill(PALETTE.white);
          }
        }

        // --- dust and sparks -------------------------------------------------
        //
        // Stepped on the playback clock like everything else, so a hit-stop
        // freezes the spray mid-air along with the blow that made it.
        stepParticles(particles, dtPlay);
        dustLayer.clear();
        sparkLayer.clear();
        for (const pt of particles) {
          const fade = pt.life / pt.max;
          if (pt.kind === 'dust') {
            dustLayer.circle(pt.x, pt.y, pt.size).fill({ color: pt.color, alpha: 0.34 * fade });
          } else {
            const sp = Math.hypot(pt.vx, pt.vy);
            const len = Math.min(7, sp * 0.03);
            const ux = sp > 0 ? pt.vx / sp : 0;
            const uy = sp > 0 ? pt.vy / sp : 0;
            sparkLayer
              .moveTo(pt.x - ux * len, pt.y - uy * len)
              .lineTo(pt.x, pt.y)
              .stroke({ width: pt.size, color: pt.color, alpha: fade });
          }
        }

        // --- strike flares ----------------------------------------------------
        flashLayer.clear();
        for (let i = flashes.length - 1; i >= 0; i--) {
          const fl = flashes[i];
          fl.life -= dtPlay;
          if (fl.life <= 0) {
            flashes.splice(i, 1);
            continue;
          }
          const to = screen.get(fl.to);
          if (!to) continue;
          const fade = fl.life / FLASH_LIFE;
          // Gold for a favourable matchup, white for neutral, red when countered.
          const color = fl.mult > 1 ? PALETTE.gold : fl.mult < 1 ? PALETTE.red : PALETTE.white;
          flashLayer.circle(to.x, to.y - 4, 4 + 10 * (1 - fade)).stroke({ width: 2.5, color, alpha: fade });
        }

        // --- commander orders ------------------------------------------------
        for (let i = bursts.length - 1; i >= 0; i--) {
          const b = bursts[i];
          b.life -= dtPlay;
          if (b.life <= 0) {
            bursts.splice(i, 1);
            continue;
          }
          const at = screen.get(b.uid);
          if (!at) continue;
          const k = 1 - b.life / ORDER_LIFE;
          // An expanding gold ring: one a match, so it should be unmistakable.
          flashLayer
            .circle(at.x, at.y - 6, 8 + 46 * k)
            .stroke({ width: 3.5 * (1 - k), color: PALETTE.gold, alpha: 1 - k });
          flashLayer
            .circle(at.x, at.y - 6, 4 + 26 * k)
            .stroke({ width: 2.5 * (1 - k), color: PALETTE.white, alpha: (1 - k) * 0.8 });
        }

        if (import.meta.env.DEV) {
          /*
           * How wide the living army stands, in body widths. The measure for
           * "the melee knots into a ball": if this collapses toward zero as men
           * die, the fight has become a point rather than a front.
           */
          let lo = Infinity;
          let hi = -Infinity;
          let hlo = Infinity;
          let hhi = -Infinity;
          let alive = 0;
          for (const q of frame.pos) {
            const sp = sprites.get(q.uid);
            if (!sp || q.hp <= 0 || !Number.isFinite(sp.sx)) continue;
            alive += 1;
            lo = Math.min(lo, sp.sx);
            hi = Math.max(hi, sp.sx);
            if (Number.isFinite(sp.homeX)) {
              hlo = Math.min(hlo, sp.homeX);
              hhi = Math.max(hhi, sp.homeX);
            }
          }
          // `home` is where the FORMATION puts the survivors, with no steering.
          // If `spread` tracks it, a narrow late fight is attrition; if `spread`
          // falls below it, the steering is pulling men into a knot.
          (window as unknown as { __battle?: unknown }).__battle = {
            app: instance,
            // The layers, so a harness can measure the FIGURES against the
            // FLOOR rather than averaging the two together.
            layers: { units: unitLayer, ground, corpses: corpseLayer },
            frame: idx,
            frames: log.frames.length,
            alive,
            cheerT,
            cheerLift,
            winner: log.winner,
            spread: alive > 1 ? (hi - lo) / (SPRITE_HEIGHT * uk * 0.62) : 0,
            home: alive > 1 && hhi > hlo ? (hhi - hlo) / (SPRITE_HEIGHT * uk * 0.62) : 0,
            particles: particles.length,
            trauma,
            ticks: elapsedTicks,
            corpses: corpseLayer.children.length,
          };
        }
        if (idx >= log.frames.length - 1 && !finishedRef.current) {
          finishedRef.current = true;
          onFinishedRef.current();
        }
      });
    })();

    return () => {
      destroyed = true;
      observer?.disconnect();
      observer = null;
      if (app) {
        app.destroy(true, { children: true });
        app = null;
      }
      host.replaceChildren();
    };
  }, [log, battle, arenaId]);

  return <div className="battle-canvas" ref={hostRef} aria-hidden="true" />;
}
